CREATE OR REPLACE FUNCTION mta_internal.execute_idempotent_mutation(p_idempotency_key text, p_request_hash text, p_operation text, p_table text, p_payload jsonb, p_where jsonb DEFAULT '{}'::jsonb, p_audit jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'mta_internal'\nAS $function$\ndeclare\n  v_existing mta_internal.idempotency_keys%rowtype;\n  v_result jsonb;\n  v_table text;\n  v_operation text;\n  v_columns text;\n  v_insert_columns text;\n  v_where_columns text;\n  v_sql text;\n  v_action text;\n  v_resource_type text;\n  v_resource_id text;\n  v_result_status text;\n  v_actor_user_id uuid;\n  v_request_id text;\n  v_correlation_id text;\n  v_audit_id uuid;\n  v_outbox_event_id uuid;\nbegin\n  if current_user <> 'service_role' and coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' then raise exception 'P9_7_SERVICE_ROLE_REQUIRED'; end if;\n  if p_idempotency_key is null or length(trim(p_idempotency_key)) < 8 then raise exception 'P9_7_INVALID_IDEMPOTENCY_KEY'; end if;\n  if p_request_hash is null or p_request_hash !~ '^[0-9a-fA-F]{64}$' then raise exception 'P9_7_INVALID_REQUEST_HASH'; end if;\n  v_operation := upper(trim(p_operation)); v_table := lower(trim(p_table));\n  if v_operation not in ('INSERT','UPDATE','DELETE') then raise exception 'P9_7_UNSUPPORTED_OPERATION'; end if;\n  if v_table not in ('mta_detainees','mta_placements','mta_movements','mta_leaves','mta_documents','mta_ai_jobs') then raise exception 'P9_7_TABLE_NOT_ALLOWED'; end if;\n  if jsonb_typeof(coalesce(p_payload, '{}'::jsonb)) <> 'object' or jsonb_typeof(coalesce(p_where, '{}'::jsonb)) <> 'object' then raise exception 'P9_7_JSON_OBJECT_REQUIRED'; end if;\n\n  select * into v_existing from mta_internal.idempotency_keys where idempotency_key = p_idempotency_key for update;\n  if found then\n    if v_existing.request_hash <> lower(p_request_hash) then raise exception 'P9_7_IDEMPOTENCY_CONFLICT'; end if;\n    if v_existing.response = '{}'::jsonb then raise exception 'P9_7_INCOMPLETE_IDEMPOTENCY_STATE'; end if;\n    return v_existing.response || jsonb_build_object('replayed', true);\n  end if;\n\n  insert into mta_internal.idempotency_keys(idempotency_key, request_hash, status, response)\n  values (p_idempotency_key, lower(p_request_hash), 'COMPLETED', '{}'::jsonb)\n  on conflict (idempotency_key) do nothing;\n\n  select * into v_existing from mta_internal.idempotency_keys where idempotency_key = p_idempotency_key for update;\n  if v_existing.request_hash <> lower(p_request_hash) then raise exception 'P9_7_IDEMPOTENCY_CONFLICT'; end if;\n  if v_existing.response <> '{}'::jsonb then return v_existing.response || jsonb_build_object('replayed', true); end if;\n  if v_operation in ('UPDATE','DELETE') and not (p_where ? 'id') then raise exception 'P9_7_PRIMARY_KEY_WHERE_REQUIRED'; end if;\n\n  if v_operation = 'INSERT' then\n    select string_agg(format('%I', k), ', ' order by k), string_agg(format('r.%I', k), ', ' order by k)\n      into v_columns, v_insert_columns\n    from jsonb_object_keys(p_payload) as k\n    join pg_attribute a on a.attrelid = format('public.%I', v_table)::regclass and a.attname = k and a.attnum > 0 and not a.attisdropped;\n    if v_columns is null then raise exception 'P9_7_EMPTY_INSERT_PAYLOAD'; end if;\n    if exists (select 1 from jsonb_object_keys(p_payload) k left join pg_attribute a on a.attrelid = format('public.%I', v_table)::regclass and a.attname = k and a.attnum > 0 and not a.attisdropped where a.attname is null) then raise exception 'P9_7_UNKNOWN_INSERT_COLUMN'; end if;\n    v_sql := format('insert into public.%I as t (%s) select %s from jsonb_populate_record(null::public.%I, $1) as r returning to_jsonb(t)', v_table, v_columns, v_insert_columns, v_table);\n    execute v_sql into v_result using p_payload;\n    if v_result is null then raise exception 'P9_7_MUTATION_RETURNED_NO_ROW'; end if;\n  elsif v_operation = 'UPDATE' then\n    if p_payload ? 'id' or p_payload ? 'created_at' then raise exception 'P9_7_IMMUTABLE_COLUMN_UPDATE'; end if;\n    select string_agg(format('%I', k), ', ' order by k) into v_columns\n    from jsonb_object_keys(p_payload) as k join pg_attribute a on a.attrelid = format('public.%I', v_table)::regclass and a.attname = k and a.attnum > 0 and not a.attisdropped;\n    if v_columns is null then raise exception 'P9_7_EMPTY_UPDATE_PAYLOAD'; end if;\n    if exists (select 1 from jsonb_object_keys(p_payload) k left join pg_attribute a on a.attrelid = format('public.%I', v_table)::regclass and a.attname = k and a.attnum > 0 and not a.attisdropped where a.attname is null) then raise exception 'P9_7_UNKNOWN_UPDATE_COLUMN'; end if;\n    select string_agg(format('t.%1$I = w.%1$I', k), ' and ' order by k) into v_where_columns\n    from jsonb_object_keys(p_where) as k join pg_attribute a on a.attrelid = format('public.%I', v_table)::regclass and a.attname = k and a.attnum > 0 and not a.attisdropped;\n    if v_where_columns is null then raise exception 'P9_7_EMPTY_UPDATE_WHERE'; end if;\n    if exists (select 1 from jsonb_object_keys(p_where) k left join pg_attribute a on a.attrelid = format('public.%I', v_table)::regclass and a.attname = k and a.attnum > 0 and not a.attisdropped where a.attname is null) then raise exception 'P9_7_UNKNOWN_UPDATE_WHERE_COLUMN'; end if;\n    v_sql := format('update public.%I as t set (%s) = (select %s from jsonb_populate_record(t, $1) as r) from jsonb_populate_record(null::public.%I, $2) as w where %s returning to_jsonb(t)', v_table, v_columns, v_columns, v_table, v_where_columns);\n    execute v_sql into v_result using p_payload, p_where;\n    if v_result is null then raise exception 'P9_7_TARGET_NOT_FOUND'; end if;\n  else\n    select string_agg(format('t.%1$I = w.%1$I', k), ' and ' order by k) into v_where_columns\n    from jsonb_object_keys(p_where) as k join pg_attribute a on a.attrelid = format('public.%I', v_table)::regclass and a.attname = k and a.attnum > 0 and not a.attisdropped;\n    if v_where_columns is null then raise exception 'P9_7_EMPTY_DELETE_WHERE'; end if;\n    if exists (select 1 from jsonb_object_keys(p_where) k left join pg_attribute a on a.attrelid = format('public.%I', v_table)::regclass and a.attname = k and a.attnum > 0 and not a.attisdropped where a.attname is null) then raise exception 'P9_7_UNKNOWN_DELETE_WHERE_COLUMN'; end if;\n    v_sql := format('delete from public.%I as t using jsonb_populate_record(null::public.%I, $1) as w where %s returning to_jsonb(t)', v_table, v_table, v_where_columns);\n    execute v_sql into v_result using p_where;\n    if v_result is null then raise exception 'P9_7_TARGET_NOT_FOUND'; end if;\n  end if;\n\n  v_action := nullif(trim(p_audit->>'action'), '');\n  v_resource_type := nullif(trim(p_audit->>'resourceType'), '');\n  v_resource_id := nullif(trim(p_audit->>'resourceId'), '');\n  v_result_status := coalesce(nullif(trim(p_audit->>'result'), ''), 'SUCCESS');\n  v_request_id := nullif(trim(p_audit->>'requestId'), '');\n  v_correlation_id := nullif(trim(p_audit->>'correlationId'), '');\n  if v_action is null or v_resource_type is null then raise exception 'P9_7_AUDIT_REQUIRED'; end if;\n  if v_result_status <> 'SUCCESS' then raise exception 'P9_7_AUDIT_SUCCESS_REQUIRED'; end if;\n  if v_resource_id is null then v_resource_id := nullif(v_result->>'id', ''); end if;\n  begin v_actor_user_id := nullif(trim(p_audit->>'actorUserId'), '')::uuid; exception when invalid_text_representation then raise exception 'P9_7_INVALID_ACTOR_USER_ID'; end;\n\n  insert into public.mta_audit_events(action, resource_type, resource_id, result, actor_user_id, request_id, correlation_id, occurred_at, metadata)\n  values (v_action, v_resource_type, v_resource_id, v_result_status, v_actor_user_id, v_request_id, v_correlation_id, now(),\n    coalesce(p_audit->'metadata', '{}'::jsonb) || jsonb_build_object('transactionBoundary','P9.7-DURABLE-v1','idempotencyKey',p_idempotency_key))\n  returning id into v_audit_id;\n\n  v_result := jsonb_build_object('ok', true, 'replayed', false, 'operation', v_operation, 'table', v_table, 'row', v_result);\n  v_outbox_event_id := gen_random_uuid();\n\n  insert into mta_internal.outbox_events(event_id,event_type,aggregate_type,aggregate_id,payload,idempotency_key,occurred_at)\n  values (\n    v_outbox_event_id, v_action, v_resource_type, v_resource_id,\n    jsonb_build_object('eventId',v_outbox_event_id,'auditEventId',v_audit_id,'operation',v_operation,'table',v_table,'row',v_result->'row','requestId',v_request_id,'correlationId',v_correlation_id,'actorUserId',v_actor_user_id,'idempotencyKey',p_idempotency_key),\n    p_idempotency_key, now()\n  );\n\n  update mta_internal.idempotency_keys set response = v_result, status = 'COMPLETED', completed_at = now() where idempotency_key = p_idempotency_key;\n  return v_result;\nend;\n$function$\n

revoke all on function mta_internal.execute_idempotent_mutation(text,text,text,text,jsonb,jsonb,jsonb) from public, anon, authenticated;
grant execute on function mta_internal.execute_idempotent_mutation(text,text,text,text,jsonb,jsonb,jsonb) to service_role;
